 14	            try db.execute(sql: "CREATE INDEX IF NOT EXISTS sessions_canonical ON sessions(canonical_id)")
 15	            try db.execute(sql: "CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), body BLOB NOT NULL)")
 16	        }
 17	    }
 18	    @discardableResult public func save(_ session: Session) throws -> Bool {
 19	        return try db.write { db in
 20	            var session = session
 21	            if let existing = try Data.fetchOne(db, sql: "SELECT body FROM sessions WHERE id=?", arguments: [session.id]) {
 22	                let previous = try JSONDecoder().decode(Session.self, from: existing)
 23	                guard session.updated >= previous.updated else { return false }
 24	                session.files = Array(Set(previous.files + session.files)).sorted()
 25	                session.instanceID = session.instanceID ?? previous.instanceID
 26	                session.migration = session.migration ?? previous.migration
 27	            }
 28	            if let nativeSource = session.nativeSource {
 29	                let candidates = try Data.fetchAll(db, sql: "SELECT body FROM sessions WHERE source=? AND native_id=?", arguments: [nativeSource, session.nativeID]).map { try JSONDecoder().decode(Session.self, from: $0) }.filter { $0.home == session.home }
 30	                if candidates.count == 1, let native = candidates.first {
 31	                    session.canonicalID = native.id; session.files = Array(Set(session.files + native.files)).sorted(); session.usage = native.usage
 32	                    session.migration = session.migration ?? native.migration
 33	                }
 34	            }
 35	            var changed = try Self.upsert(db, session)
 36	            if session.source != "acp" {
 37	                let aliases = try Data.fetchAll(db, sql: "SELECT body FROM sessions WHERE source='acp' AND native_id=?", arguments: [session.nativeID]).map { try JSONDecoder().decode(Session.self, from: $0) }
 38	                for var alias in aliases where alias.nativeSource == session.source && alias.home == session.home {
 39	                    alias.canonicalID = session.id; alias.usage = session.usage; alias.files = Array(Set(alias.files + session.files)).sorted()
 40	                    alias.migration = alias.migration ?? session.migration
 41	                    changed = try Self.upsert(db, alias) || changed
 42	                }
 43	            }
 44	            return changed
 45	        }
 46	    }
 47	    private static func upsert(_ db: Database, _ session: Session) throws -> Bool {
 48	        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
 49	        let body = try encoder.encode(session)
 50	        guard try Data.fetchOne(db, sql: "SELECT body FROM sessions WHERE id=?", arguments: [session.id]) != body else { return false }
 51	        var summary = session; summary.messages = []
 52	        let summaryData = try encoder.encode(summary)
 53	        try db.execute(sql: "INSERT INTO sessions(id,source,native_id,title,project,updated,body,summary,search,canonical_id) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title, project=excluded.project, updated=excluded.updated, body=excluded.body, summary=excluded.summary, search=excluded.search, canonical_id=excluded.canonical_id", arguments: [session.id, session.source, session.nativeID, session.title, session.project, session.updated, body, summaryData, session.title + "\n" + session.messages.map(\.text).joined(separator: "\n"), session.canonicalID])
 54	        return true
 55	    }
 56	    public func list(query: String = "", limit: Int = Int.max) throws -> [Session] {
 57	        try db.read { db in
 58	            let escaped = query.replacingOccurrences(of: "\\", with: "\\\\").replacingOccurrences(of: "%", with: "\\%").replacingOccurrences(of: "_", with: "\\_")
 59	            return try Data.fetchAll(db, sql: "SELECT summary FROM sessions s WHERE search LIKE ? ESCAPE '\\' AND NOT EXISTS (SELECT 1 FROM sessions a WHERE a.canonical_id=s.id) ORDER BY updated DESC LIMIT ?", arguments: ["%\(escaped)%", limit]).map { try JSONDecoder().decode(Session.self, from: $0) }
 60	        }
 61	    }
 62	    public func session(_ id: String) throws -> Session? {
 63	        try db.read { db in
 64	            try Data.fetchOne(db, sql: "SELECT body FROM sessions WHERE id=?", arguments: [id]).map { try JSONDecoder().decode(Session.self, from: $0) }
 65	        }
 66	    }
