 68	        try db.read { db in
 69	            try Data.fetchOne(db, sql: "SELECT body FROM settings WHERE id=1").map { try JSONDecoder().decode(Settings.self, from: $0) } ?? Settings()
 70	        }
 71	    }
 72	    public func saveSettings(_ settings: Settings) throws {
 73	        let data = try JSONEncoder().encode(settings)
 74	        try db.write { db in try db.execute(sql: "INSERT INTO settings(id,body) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET body=excluded.body", arguments: [data]) }
 75	    }
